90	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
91	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
92	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
93	  // GPA still unset throws in the sweep (no silent transport via a bogus
94	  // address). The simulator passes the real value from platform.main_memory.
95	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
96	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
97	  // every CSR, the prior behavior -- so existing call sites are unchanged.
98	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
99	                        AndesCaps caps = AndesCaps::all())
100	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
101	  {}
102	
103	  // Opt-in GPR block-load (prototype): reload x1..x31 with a Program-Buffer
104	  // ld-sweep from the scratch page instead of 31 abstract register writes.
105	  // Off by default so existing callers/tests are unchanged; the simulator
106	  // enables it and stages the values via stage_gpr_to_scratch.
107	  void set_gpr_block_load(bool on) { gpr_block_load_ = on; }
108	
109	  void resume(const hybrid_state_v1& state)
110	  {
111	    if (state.magic != HYBRID_STATE_MAGIC)
112	      throw std::runtime_error("ResumeDriver::resume: bad magic");
113	    if (state.version != HYBRID_STATE_VERSION)
114	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
115	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
116	    if (state.priv == 2 || state.priv > 3)
117	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
118	
119	    // dmactive must transition 0->1 in its own write before any other
120	    // DMCONTROL bit is honored (RISC-V Debug Spec).
121	    bus_.write(kDmcontrol, kDmcontrolDmactive);
122	    request_halt();
123	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
124	
125	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
126	    // accepted (FS or VS == Off disables the extension and the hart NACKs
127	    // the writes). The drained state.mstatus may legitimately carry FS or
128	    // VS at Off (e.g. an OS context-switched the regs away before the
129	    // trigger fired) -- gating the write on the drained field skips the
130	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
131	    // write mstatus when either extension is in scope; force-OR Initial
132	    // when the drained field is Off. This enable is local to the vsim
133	    // phase; the state.mstatus written to the handoff file is left
134	    // unmodified.
135	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
136	      uint64_t enable_mstatus = state.mstatus;
137	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
138	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
139	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
140	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
141	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
142	    }
143	
144	    // FPR restore (requires mstatus.FS enabled above).
145	    if (state.flags & HYBRID_FLAG_FP) {
146	      for (uint16_t i = 0; i < 32; ++i)
147	        write_64bit_register(regno_fpr(i), state.fpr[i]);
148	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
149	      // fallback scratch x5 is overwritten by the GPR loop below.
150	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
151	    }
152	
153	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
154	    // the GPR loop overwrites x5 afterward so state is preserved).
155	    if (state.flags & HYBRID_FLAG_V) {
156	      // V data regfile: reload v0..v31 from the shared scratch region via the
157	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
158	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
159	      // the restore then overwrites with the architectural values. The sweep
160	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
161	      // below restores all three. The scratch is vlenb-packed
162	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
163	      if (scratch_gpa_ == kVScratchGpaUnset)
164	        throw std::runtime_error(
165	          "ResumeDriver::resume: V state present but scratch GPA unset");
166	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
167	
168	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
169	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
170	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
171	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
172	      write_64bit_register(regno_gpr(5), state.vl);
173	      write_64bit_register(regno_gpr(6), state.vtype);
174	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
175	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
176	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
177	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
178	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
179	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
180	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
181	    }
182	
183	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
184	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
185	    // in the drained privilege; M-mode states skip the write (prv already 3).
186	    // Before the GPR loop: a PB fallback would clobber scratch x5.
187	    if (state.priv != 3) {
188	      // L2 slice: with PMP implemented and no matching entry, every S/U
189	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
190	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
191	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
192	      // RV64. Tolerant writes: entries beyond what the hart implements
193	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
194	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
195	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
196	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
197	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
198	
199	      const uint64_t dcsr =
200	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
201	      write_csr_abstract_or_pb(kCsrDcsr,
202	                               (dcsr & ~uint64_t{0x3}) | state.priv);
203	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
204	      // silently measure the ROI in the wrong privilege. Verify and abort.
205	      const uint64_t got =
206	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
207	        & 0x3u;
208	      if (got != state.priv)
209	        throw std::runtime_error(
210	          "ResumeDriver::resume: engine does not implement privilege level "
211	          + std::to_string(state.priv)
212	          + " (dcsr.prv pinned to " + std::to_string(got)
213	          + "); pick an S/U-capable engine");
214	    }
215	
216	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
217	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
218	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
219	    // region leaves room; otherwise fall back to per-register abstract writes.
220	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
221	        && gpr_scratch_fits(state.vlenb)) {
222	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
223	    } else {
224	      for (uint16_t i = 1; i < 32; ++i)
225	        write_64bit_register(regno_gpr(i), state.gpr[i]);
226	    }
227	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
228	
229	    write_csr_tolerant(kCsrMtvec, state.mtvec);
230	
231	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
232	    // register with no hardware side effects, legal to use inside a trap-free
233	    // ROI. Restore it so a value stashed before the handoff survives into the
234	    // vsim phase.
235	    write_csr_tolerant(kCsrMscratch, state.mscratch);
236	
237	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
238	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
239	    // value stashed before the handoff must survive into the vsim phase (same
240	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
241	    // hardware-driven pending bits, or mtval on a core that hardwires it)
242	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
243	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
244	    write_csr_tolerant(kCsrMepc,   state.mepc);
245	    write_csr_tolerant(kCsrMcause, state.mcause);
246	    write_csr_tolerant(kCsrMtval,  state.mtval);
247	    write_csr_tolerant(kCsrMie,    state.mie);
248	    write_csr_tolerant(kCsrMip,    state.mip);
249	
250	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
251	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
252	    // caches) but has no cache model, so without this the cycle engine resumes
253	    // at the ROI with caches at their reset default -- DISABLED -- and the
254	    // whole measured window runs uncached, inflating it severalfold. Tolerant
255	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
256	    // write as a no-op, and a drained 0 (caches were off) restores the reset
257	    // state, so this is always safe to issue.
258	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
259	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
260	
261	    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
262	    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
263	    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
264	    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
265	    // mcache_ctl: without them the cycle engine resumes with the wrong memory
266	    // system or faults on the first CoDense/DSP op in the window. caps_ gates
267	    // each write to the CSRs the TARGET core actually implements (from its
268	    // config.inc): restoring an absent custom CSR is NOT a clean no-op -- the
269	    // abstract write stalls the DM handshake (observed: ucode without DSP,
270	    // mecc_code without ECC). HYBRID_ANDES_CSR_LIST is the single source of
271	    // truth shared with the plugin drain, StateDrain, and state_diff.
272	    if (state.flags & HYBRID_FLAG_ANDES) {
273	#define X(field, addr, name) \
274	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
275	      HYBRID_ANDES_CSR_LIST(X)
276	#undef X
277	      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
278	      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
279	      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
280	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
281	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
282	          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
283	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
284	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
285	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
286	    }
287	
288	    // M-ext CSR block (v4): the writable M-mode CSRs across the whole SPA, each
289	    // capability-gated by address exactly like the Andes block above. caps_
290	    // skips any the target core lacks (most on an M-only core), so the absent
291	    // ones never stall the DM. Same single-source X-macro shared with the plugin
292	    // drain, StateDrain, and state_diff.
293	    if (state.flags & HYBRID_FLAG_M_EXT) {
294	#define X(field, addr, name) \
295	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
296	      HYBRID_M_EXT_CSR_LIST(X)
297	#undef X
298	    }
299	
300	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
301	    // from QEMU1's drain value. Without this, vsim's local counter starts
302	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
303	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
304	    // overwrite here as the GPR loop already ran.
305	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
306	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
307	
308	    clear_cmderr_if_set();
309	    request_resume();
310	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
311	                   "ResumeDriver resume");
312	  }
313	
314	private:
315	  void request_halt()
316	  {
317	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
318	  }
319	
320	  void request_resume()
321	  {
322	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
323	  }
324	
325	  void write_64bit_register(uint16_t regno, uint64_t value)
326	  {
327	    write_register_abstract(bus_, regno, value);
328	  }
329	
330	  // GPR block-load: seed x31 with the scratch GPA (the base pointer), then ld
331	  // x1..x31 from their slots via the Program Buffer. So 31 registers cost one
332	  // abstract write + a few PB executions instead of 31 abstract writes. `ld`'s
333	  // 12-bit offset spans every slot (<= 240). x31 is the base, so its own ld is
334	  // emitted LAST: it may clobber the base only after every other load has used
335	  // it. (x31's slot is the mapping's final word, which the memory decoder now
336	  // returns correctly.)
337	  void restore_gprs_via_pb(uint64_t gpr_gpa)
338	  {
339	    // The Program Buffer holds abstractcs.progbufsize entries (this DM reports
340	    // 8); reserve one slot for the terminating ebreak, so at most
341	    // progbufsize-1 loads per execution. x31 stays the base through every load
342	    // except its own (emitted last), so batches compose freely.
343	    const uint32_t progbufsize = (bus_.read(kAbstractcs) >> 24) & 0x1Fu;
344	    const std::size_t max_lds = (progbufsize > 1) ? progbufsize - 1u : 1u;
345	    write_register_abstract(bus_, regno_gpr(31), gpr_gpa);  // base pointer
346	    std::array<uint32_t, 32> batch{};
347	    std::size_t n = 0;
348	    for (uint8_t k = 1; k < 32; ++k) {  // x1..x31; x31 (the base) loaded last
349	      batch[n++] = encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8));
350	      if (n == max_lds || k == 31) {
351	        exec_progbuf(bus_, std::span<const uint32_t>{batch.data(), n});
352	        n = 0;
353	      }
354	    }
355	  }
356	
357	  // Abstract-first CSR write with Program Buffer fallback.
358	  // Tries an abstract register write; if the DM signals cmderr, clears it,
359	  // stages the value in scratch_gpr via abstract GPR write, then executes a
360	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
361	  // to x5 (t0) which the GPR restore loop overwrites later.
362	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
363	                                 uint8_t scratch_gpr = 5)
364	  {
365	    write_64bit_register(regno_csr(csr), value);
366	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
367	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
368	    write_64bit_register(regno_gpr(scratch_gpr), value);
369	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
370	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
371	  }
372	
373	  // Write a CSR-addressable register and clear any cmderr the DM raised.
374	  // Used for CSRs whose abstract-access support may be implementation
375	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
376	  // remaining writes.
377	  void write_csr_tolerant(uint16_t csr, uint64_t value)
378	  {
379	    write_64bit_register(regno_csr(csr), value);
380	    clear_cmderr_if_set();
381	  }
382	
383	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
384	  // is rejected until the bits are W1C-cleared. We tolerate per-register
385	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
386	  // error before resuming so the hart isn't left in a stuck state.
387	  // B17: record the last observed non-zero cmderr and a clear count so a
388	  // partially-broken restore is observable via the public accessors
389	  // instead of silently swallowed.
390	  void clear_cmderr_if_set()
391	  {
392	    const auto status = bus_.read(kAbstractcs);
393	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
394	    if (code != 0u) {
395	      last_observed_cmderr_ = code;
396	      ++cmderr_clear_count_;
397	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
398	    }
399	  }
400	
401	  DmiBus& bus_;
402	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
403	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
404	  bool gpr_block_load_ = false;               // opt-in GPR PB ld-sweep
405	  uint32_t last_observed_cmderr_ = 0;
406	  uint64_t cmderr_clear_count_   = 0;
407	
408	public:
409	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
410	  // at least one abstract write tripped a sticky cmderr the restore
411	  // tolerated by clearing. cmderr_clear_count() is the total number of
412	  // such clears across all calls into clear_cmderr_if_set() this run.
413	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
414	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
415	};
416	
417	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
418	// via an Abstract Command. Halts-and-reads contract: caller must have the
419	// hart in the halted state. Shared by StateDrain (drain at exit). If
420	// abstractcs.cmderr goes sticky after the command, the helper clears it and
421	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
422	// instead of corrupting the adjacent field.
423	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
424	                                     const char* poll_label
425	                                       = "read_register_64")
426	  -> std::optional<uint64_t>
427	{
428	  using RD = ResumeDriver;
429	  bus.write(RD::kCommand,
430	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
431	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
432	  const auto status = bus.read(RD::kAbstractcs);
433	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
434	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
435	    return std::nullopt;
436	  }
437	  const uint64_t lo = bus.read(RD::kData0);
438	  const uint64_t hi = bus.read(RD::kData1);
439	  return lo | (hi << 32);
440	}
441	
442	inline auto read_register_64(DmiBus& bus, uint16_t regno,
443	                             const char* poll_label = "read_register_64")
444	  -> uint64_t
445	{
446	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
447	}
448	
449	}  // namespace hybrid
